293: number tetrahedron_volume(ref const(Vector3) p0, ref const(Vector3) p1,
294:                           ref const(Vector3) p2, ref const(Vector3) p3)
295: {
296:     // Was return dot(p3-p0, cross(p1-p0, p2-p0)) / 6.0;
297:     // Now, expand up to components to avoid allocation.
298:     number dx01=p1.x-p0.x; number dy01=p1.y-p0.y; number dz01=p1.z-p0.z;
299:     number dx02=p2.x-p0.x; number dy02=p2.y-p0.y; number dz02=p2.z-p0.z;
300:     number cx, cy, cz;
301:     cross_product(dx01, dy01, dz01, dx02, dy02, dz02, cx, cy, cz);
302:     number dx03=p3.x-p0.x; number dy03=p3.y-p0.y; number dz03=p3.z-p0.z;
303:     return dot_product(dx03, dy03, dz03, cx, cy, cz) / 6.0;
304: } // end tetrahedron_volume()
